#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int minSwaps(std::vector<int>& nums) {
        int n = nums.size();

        auto getDigitSum = [](int x) {
            int sum = 0;
            while (x > 0) {
                sum += x % 10;
                x /= 10;
            }
            return sum;
        };

        struct Item {
            int digitSum;
            int val;
            int origIdx;
        };

        std::vector<Item> items(n);
        for (int i = 0; i < n; ++i) {
            items[i] = {getDigitSum(nums[i]), nums[i], i};
        }

        std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
            if (a.digitSum != b.digitSum) {
                return a.digitSum < b.digitSum;
            }
            return a.val < b.val;
        });

        std::vector<int> target(n);
        for (int i = 0; i < n; ++i) {
            target[items[i].origIdx] = i;
        }

        std::vector<bool> visited(n, false);
        int cycles = 0;

        for (int i = 0; i < n; ++i) {
            if (!visited[i]) {
                cycles++;
                int curr = i;
                while (!visited[curr]) {
                    visited[curr] = true;
                    curr = target[curr];
                }
            }
        }

        return n - cycles;
    }
};
